<?php require __DIR__.'/../config/bootstrap.php'; require_admin(); /* This check was missing: the POST handler below ran before includes/admin_header.php performed the login check, so anyone holding a CSRF token from the public contact form could add or delete records while signed out. */ $admin_title='Testimonials'; $imgM=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$name=post_text('client_name');$role=post_text('role_company');$quote=post_text('quote');$rating=max(1,min(5,post_int('rating',5)));if($name===''||$quote==='')throw new UserMessageException('A testimonial needs both a client name and a quote.');$active=isset($_POST['active'])?1:0;$img=save_upload($_FILES['image']??['error'=>UPLOAD_ERR_NO_FILE],'uploads/testimonials',$imgM,5*1024*1024,true);if($id){$old=db()->prepare('SELECT image FROM testimonials WHERE id=?');$old->execute([$id]);$old=$old->fetch();$sql='UPDATE testimonials SET client_name=?,role_company=?,quote=?,rating=?,active=?';$params=[$name,$role,$quote,$rating,$active];if($img){$sql.=',image=?';$params[]=$img;} $sql.=' WHERE id=?';$params[]=$id;db()->prepare($sql)->execute($params);if($img&&$old)delete_file($old['image']);}else{db()->prepare('INSERT INTO testimonials(client_name,role_company,quote,rating,image,active) VALUES(?,?,?,?,?,?)')->execute([$name,$role,$quote,$rating,$img??'',$active]);}flash('success','Testimonial saved.');}elseif($a==='delete'){db()->prepare('DELETE FROM testimonials WHERE id=?')->execute([post_int('id')]);flash('success','Testimonial deleted.');}header('Location: '.url('admin/testimonials.php'));exit;}catch(Throwable $e){flash_exception($e);header('Location: '.url('admin/testimonials.php'));exit;}}$edit=null;if(isset($_GET['edit'])){$st=db()->prepare('SELECT * FROM testimonials WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$items=db()->query('SELECT * FROM testimonials ORDER BY created_at DESC')->fetchAll();require __DIR__.'/../includes/admin_header.php'; ?><div class="admin-card"><h2><?=$edit?'Edit testimonial':'Add testimonial'?></h2><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-cols"><div><label>Client name</label><input required name="client_name" value="<?=e($edit['client_name']??'')?>"></div><div><label>Role / company</label><input name="role_company" value="<?=e($edit['role_company']??'')?>"></div><div class="wide"><label>Quote</label><textarea required name="quote" rows="5"><?=e($edit['quote']??'')?></textarea></div><div><label>Rating</label><select name="rating"><?php for($i=5;$i>=1;$i--):?><option <?=$i==(int)($edit['rating']??5)?'selected':''?>><?=$i?></option><?php endfor;?></select></div><div><label>Photo</label><input type="file" name="image" accept=".jpg,.jpeg,.png,.webp"></div></div><label class="check"><input type="checkbox" name="active" <?=($edit===null||!empty($edit['active']))?'checked':''?>> Show publicly</label><button class="admin-button">Save Testimonial</button></form></div><div class="admin-card"><table class="table"><thead><tr><th>Client</th><th>Rating</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><strong><?=e($x['client_name'])?></strong><small><?=e($x['role_company'])?></small></td><td><?=str_repeat('★',(int)$x['rating'])?></td><td><?=!empty($x['active'])?'Visible':'Hidden'?></td><td class="actions"><a href="?edit=<?=(int)$x['id']?>">Edit</a><form method="post" data-confirm="Delete this testimonial?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/admin_footer.php'; ?>